function ortCtx(){ const p=rP(ORT); const frase=rP(['A palavra “{}” apareceu no texto da prova.','O instrutor escreveu “{}” no quadro.','No relatório, constava a palavra “{}”.']); return siAny({s:frase,c:p[0],w:p[1],x:'Grafia correta: '+p[0]+'.'},['cloze','tf']); }
function ortAcento(){ const g=rP(ACENTO), w=rP(g.w); return arCh('Por que a palavra **'+w+'** é acentuada?',g.r,ACENTO.filter(x=>x!==g).map(x=>x.r),{x:'"'+w+'": '+g.r+'.'}); }
function ortAcentoPar(){ const g=rP(ACENTO), [a,b]=rN(g.w,2), right=a+' e '+b, ws=[]; let t=0;
  while(ws.length<4&&t<40){ t++; const [g1,g2]=rN(ACENTO,2); const s=rP(g1.w)+' e '+rP(g2.w); if(ws.indexOf(s)<0) ws.push(s); }
  return arCh('Assinale a alternativa em que as duas palavras são acentuadas **pela mesma regra**.',right,ws,{x:'"'+a+'" e "'+b+'": '+g.r+'.'}); }
function ortAcordo(){ if(rC(.5)){ const w=rP(SEM_ACENTO); return arTF('Depois do Acordo Ortográfico, a palavra “'+w+'” se escreve sem acento (ou sem trema).',true,{x:'Correto: "'+w+'". Perderam o acento os ditongos abertos ei/oi em paroxítonas (ideia, heroico), os hiatos ee/oo (creem, voo), o i/u tônico após ditongo em paroxítona (feiura), vários diferenciais (para, pelo, polo, pera) e o trema (linguiça).'}); }
  const h=rP(HIFEN); return arCh('Qual forma segue o Acordo Ortográfico?',h[0],[h[1]],{x:h[2]}); }
function ortTodas(){ const good=()=>rN(ORT,3).map(p=>p[0]); const bad=()=>{ const ws=rN(ORT,3), k=rI(0,2); return ws.map((p,i)=>i===k?rP(p[1]):p[0]); };
  const R=good().join(', '), W=[bad().join(', '),bad().join(', '),bad().join(', '),bad().join(', ')];
  return arCh('Assinale a alternativa em que **todas** as palavras estão escritas corretamente.',R,W,{x:'Correta: '+R+'.'}); }
