function semParon(){ const p=rP(PARON), [s,k]=rP(p[2]); return {s,c:p[0][k],w:[p[0][1-k]],x:'"'+p[0][0]+'" = '+p[1][0]+'; "'+p[0][1]+'" = '+p[1][1]+'.'}; }
function semSign(){ const p=rP(PARON), k=rI(0,1); return arCh('Qual o significado de **'+p[0][k]+'**?',p[1][k],[p[1][1-k]].concat(rN(PARON.filter(x=>x!==p),3).map(x=>x[1][rI(0,1)])),{x:'"'+p[0][0]+'" = '+p[1][0]+'; "'+p[0][1]+'" = '+p[1][1]+'.'}); }
