/* ---------- CLASSES DE PALAVRAS ---------- */
const CL_NOME={sub:'Substantivo',adj:'Adjetivo',art:'Artigo',num:'Numeral',pron:'Pronome',verb:'Verbo',adv:'Advérbio',prep:'Preposição',conj:'Conjunção',interj:'Interjeição'};
const CL_FR=['Os[art] bombeiros[sub] chegaram[verb] rapidamente[adv] ao local.','A[art] viatura[sub] nova[adj] saiu[verb] cedo[adv].','Ela[pron] estudou[verb] muito[adv] para[prep] a prova.','Três[num] soldados[sub] resgataram[verb] a vítima.','Nossa[pron] equipe[sub] trabalhou[verb] mas[conj] não venceu.',
 'Nossa![interj] Que[adv] incêndio[sub] enorme[adj]!','O[art] correr[sub] diário[adj] melhora[verb] o fôlego.','Ele[pron] falou[verb] alto[adv] durante[prep] a reunião.','O cadete[sub] atento[adj] percebeu[verb] o erro.','Saímos[verb] porque[conj] chovia[verb] muito.',
 'Aquele[pron] prédio[sub] alto[adj] foi[verb] evacuado.','Ontem[adv] recebemos[verb] duas[num] denúncias[sub].','Com[prep] calma[sub], tudo[pron] se resolve[verb].','Ai![interj] O fogo[sub] queimou[verb] minha[pron] mão.','Embora[conj] cansados[adj], eles[pron] continuaram[verb].',
 'O[art] primeiro[num] colocado[sub] recebeu[verb] a medalha.','Alguém[pron] deixou[verb] a porta[sub] aberta[adj].','Talvez[adv] chova[verb] amanhã[adv].','A coragem[sub] é[verb] essencial[adj].','Os alunos[sub] estudam[verb] e[conj] treinam[verb].'];
const QUE_SE=[['O livro **que** li era ótimo.','Pronome relativo'],['Espero **que** você passe.','Conjunção integrante'],['Estudou tanto **que** passou.','Conjunção consecutiva'],['Ele é mais forte **que** o irmão.','Conjunção comparativa'],['**Que** bonito foi o desfile!','Advérbio de intensidade'],['**Que** horas são?','Pronome interrogativo'],['Tenho **que** sair cedo.','Preposição'],['Eu é **que** sei o caminho.','Palavra expletiva (de realce)'],
 ['Vendem-**se** casas.','Pronome apassivador'],['Precisa-**se** de ajudantes.','Índice de indeterminação do sujeito'],['Ele **se** feriu no treino.','Pronome reflexivo'],['**Se** chover, não vou.','Conjunção condicional'],['Não sei **se** ele vem.','Conjunção integrante'],['Ele **se** queixou do barulho.','Parte integrante do verbo'],['Os dois **se** abraçaram.','Pronome recíproco']];
const MUDA=[['O **correr** faz bem à saúde.','Substantivo'],['Ele deu um **não** como resposta.','Substantivo'],['Ele fala **alto**.','Advérbio'],['O prédio **alto** foi evacuado.','Adjetivo'],['Havia **bastante** trabalho.','Pronome indefinido (adjetivo)'],['Estudou **bastante**.','Advérbio'],['Ela ficou **meio** tonta.','Advérbio'],['Comprou **meio** litro.','Numeral'],['**Só** ele chegou.','Advérbio (palavra denotativa)'],['Ele ficou **só**.','Adjetivo'],
 ['Encontrei-**a** no quartel.','Pronome oblíquo'],['Vou **a** Curitiba.','Preposição'],['**A** equipe chegou.','Artigo'],['Fiz **como** mandaram.','Conjunção conformativa'],['Corre **como** um atleta.','Conjunção comparativa'],['**Como** estava cansado, dormiu.','Conjunção causal'],['**Como** você chegou aqui?','Advérbio interrogativo']];
function clParse(fr){ const toks=fr.split(' '), parts=[], tags=[]; toks.forEach(t=>{ const m=t.match(/^(.*?)\[(\w+)\](.*)$/); if(m){ parts.push(m[1]+m[3]); tags.push(m[2]); } else { parts.push(t); tags.push(null); } }); return {parts,tags}; }
function clPick(basic){ let g=0; while(g++<30){ const {parts,tags}=clParse(rP(CL_FR)); const avail=[...new Set(tags.filter(Boolean))].filter(t=>!basic||['sub','adj','verb','adv'].indexOf(t)>=0); const want=rP(avail); const idx=tags.map((t,i)=>t===want?i:-1).filter(i=>i>=0); if(idx.length!==1) continue;
  return arPick('Toque no **'+CL_NOME[want].toLowerCase()+'**.',parts,idx[0],{x:'"'+parts[idx[0]].replace(/[.,!?]/g,'')+'" é '+CL_NOME[want].toLowerCase()+'.'}); } return clQual(); }
function clQual(){ const {parts,tags}=clParse(rP(CL_FR)); const idxs=tags.map((t,i)=>t?i:-1).filter(i=>i>=0), i=rP(idxs); const w=parts[i].replace(/[.,!?]/g,'');
  return arCh('Em “'+parts.join(' ')+'”, a palavra **'+w+'** é:',CL_NOME[tags[i]],Object.keys(CL_NOME).filter(k=>k!==tags[i]).map(k=>CL_NOME[k]),{x:'"'+w+'": '+CL_NOME[tags[i]].toLowerCase()+'.'}); }
const clBank=(bank,q)=>()=>{ const it=rP(bank); return arCh(it[0]+'\n'+q,it[1],[...new Set(bank.map(x=>x[1]))].filter(x=>x!==it[1]),{x:it[0].replace(/\*\*/g,'')+' → '+it[1]+'.'}); };
