const TERMO_NOME={suj:'Sujeito',v:'Verbo',OD:'Objeto direto',OI:'Objeto indireto',AADV:'Adjunto adverbial',AP:'Agente da passiva',AP2:'Aposto',VOC:'Vocativo',PO:'Predicativo do objeto',PS:'Predicativo do sujeito',CN:'Complemento nominal',AADN:'Adjunto adnominal'};
