const conRel=()=>rP(Object.keys(CON_FR));
function conFill(){ const r=conRel(), fr=rP(CON_FR[r]), c=rP(CON[r]); const cap=fr.startsWith('{}'); const f=w=>cap?w[0].toUpperCase()+w.slice(1):w;
  const wr=Object.keys(CON_FR).filter(k=>k!==r).map(k=>f(rP(CON[k]))); return arCh('Complete com o conectivo que dá sentido à frase:\n'+fr.replace('{}','_____'),f(c),wr,{x:'A relação é de '+r.toLowerCase()+': "'+c+'".'}); }
function conSubst(alter){ const r=conRel(), fr=rP(CON_FR[r]), [a,b]=rN(CON[r],2); if(!b) return conFill(); const cap=fr.startsWith('{}'); const f=w=>cap?w[0].toUpperCase()+w.slice(1):w; const shown=fr.replace('{}','**'+f(a)+'**');
  const others=Object.keys(CON).filter(k=>k!==r&&k!=='Adição').map(k=>rP(CON[k]));
  if(!alter) return arCh(shown+'\nSem alterar o sentido, o conectivo destacado pode ser substituído por:',b,others,{x:'"'+a+'" e "'+b+'" expressam '+r.toLowerCase()+'.'});
  const same=CON[r].filter(x=>x!==a); if(same.length<3) return conSubst(false); return arCh(shown+'\nQual substituição **altera** o sentido da frase?',rP(others),rN(same,4),{x:'Os demais expressam '+r.toLowerCase()+', como "'+a+'".'}); }
