function itTxt(t){ return '**Texto:**\n'+t.tx; }
arGame({id:'ar-port-int',s:'port',t:'port-int',nome:'Leitor de elite',ic:'“ ”',desc:'Informação explícita, inferência, extrapolação e tema, como a banca cobra.',lv:[
  {d:'Segundo o texto: a informação está escrita.',g:[()=>{ const t=rP(TEXTOS); return arCh(itTxt(t)+'\n\nSegundo o texto, é correto afirmar que:',rP(t.af),t.no,{x:'Está escrito no texto. As demais extrapolam ou contradizem o texto.'}); },()=>{ const t=rP(TEXTOS), ok=rC(.5); return arTF(itTxt(t)+'\n\nO texto afirma: “'+(ok?rP(t.af):rP(t.no))+'”',ok,{x:ok?'Está no texto.':'O texto não diz isso.'}); }]},
  {d:'Vocabulário no contexto e tema central.',g:[()=>{ const t=rP(TEXTOS); return arCh(itTxt(t)+'\n\nNo texto, a palavra **'+t.voc[0]+'** significa:',t.voc[1],t.voc[2].split('|'),{x:'No contexto: '+t.voc[1]+'.'}); },()=>{ const t=rP(TEXTOS); return arCh(itTxt(t)+'\n\nO tema central do texto é:',t.tema,t.temaW,{x:t.tema+'.'}); }]},
  {d:'Inferência: o que se conclui, sem estar escrito.',g:[()=>{ const t=rP(TEXTOS); return arCh(itTxt(t)+'\n\nPode-se **inferir** do texto que:',rP(t.inf),t.no,{x:'É uma conclusão apoiada no texto. As outras extrapolam.'}); }]},
  {d:'Assinale a INCORRETA; o que não se pode afirmar.',g:[()=>{ const t=rP(TEXTOS); return arCh(itTxt(t)+'\n\nDe acordo com o texto, é **incorreto** afirmar que:',rP(t.no),t.af.concat(t.inf),{x:'Essa afirmação não se sustenta no texto.'}); }]},
  {d:'Classifique: escrito, inferível ou extrapolação.',g:[()=>{ const t=rP(TEXTOS); const it=rN(t.af,2).map(s=>[s,0]).concat(rN(t.inf,1).map(s=>[s,1]),rN(t.no,2).map(s=>[s,2])); return arSort(itTxt(t)+'\n\nClassifique cada afirmação:',['Está no texto','Pode-se inferir','Não se pode afirmar'],rS(it),{x:'Explícito: está escrito. Inferência: conclusão apoiada no texto. Extrapolação: vai além do que o texto permite.'}); }]}]});
